// Runs ONCE for all input items, returns exactly ONE item.
// Fixes the double-execution bug: a Set node would emit one item
// per input row (2 rows = 2 items), causing Get Pending Users to
// run twice and return 20,000 rows instead of 10,000.

const items   = $input.all();
const guildId = items.find(i => i.json.setting === 'guild_id')?.json.value ?? '';
const roleId  = items.find(i => i.json.setting === 'role_id')?.json.value  ?? '';

if (!guildId) throw new Error('guild_id row not found in Config sheet');
if (!roleId)  throw new Error('role_id row not found in Config sheet');

return [{ json: { guildId, roleId } }];

// ─────────────────────────────────────────────────────────────────
// Assign a Discord role using n8n's built-in credential helper.
//
// $json here is the current loop item — it has user_id and row_number
// directly, no Merge node or pairedItem lookup needed.
//
// $helpers.httpRequestWithAuthentication uses the Discord Bot
// credential stored in n8n — the token never touches the sheet.
// ─────────────────────────────────────────────────────────────────

const userId    = $json.user_id;
const rowNumber = $json.row_number;

const config  = $('⚙️ Extract Config').first().json;
const guildId = config.guildId;
const roleId  = config.roleId;

const url       = `https://discord.com/api/v10/guilds/${guildId}/members/${userId}/roles/${roleId}`;
const timestamp = new Date().toISOString();

let status = 'done', errorMsg = '';

try {
  const response = await $helpers.httpRequestWithAuthentication(
    'discordBotApi',
    {
      method:                 'PUT',
      url,
      headers: {
        'Content-Type':       'application/json',
        'X-Audit-Log-Reason': 'Mass role assignment'
      },
      returnFullResponse:     true,
      ignoreHttpStatusErrors: true
    }
  );

  const code = response.statusCode;
  const body = typeof response.body === 'string'
    ? response.body
    : JSON.stringify(response.body ?? '');

  if (code === 204 || code === 200) {
    status   = 'done';
    errorMsg = '';

  } else if (code === 404) {
    status   = 'not_in_server';
    errorMsg = 'User not found in server — they may have left (404)';

  } else if (code === 429) {
    status   = 'rate_limited';
    errorMsg = `Discord rate limited the request (429): ${body.substring(0, 100)}`;

  } else if (code === 403) {
    status   = 'failed';
    errorMsg = 'Bot lacks MANAGE_ROLES or target role is above bot in hierarchy (403)';

  } else {
    status   = 'failed';
    errorMsg = `HTTP ${code}: ${body.substring(0, 200)}`;
  }

} catch (err) {
  status   = 'failed';
  errorMsg = `Network error: ${err.message?.substring(0, 200) ?? 'unknown'}`;
}

// Rate limiting: ~4 requests/second, safely under Discord's limit.
await new Promise(r => setTimeout(r, 250));

return [{
  json: { user_id: userId, row_number: rowNumber, status, timestamp, error: errorMsg }
}];
